pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testFuzz_property(uint256 nCalls) public {
        vm.assume(nCalls <= 100);
        vm.assume(nCalls > 0);
        for (uint256 i = 0; i < nCalls; i++) {
            c.newGrantProposal(address(0), 0);
        }
        assertTrue(c.proposalCount() == nCalls);
    }
}
